def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people_patches = image_patch.find("people")
    if len(people_patches) < 3:
        return image_patch

    # Sort people by their vertical center
    people_patches.sort(key=lambda p: p.vertical_center)

    # Find the person who is not looking at the others
    for i, person in enumerate(people_patches):
        looking_at_others = False
        for j, other_person in enumerate(people_patches):
            if i != j and person.overlaps_with(other_person.left, other_person.lower, other_person.right, other_person.upper):
                looking_at_others = True
                break
        if not looking_at_others:
            return person

    # If no one is clearly looking at the others, return the tallest person
    return max(people_patches, key=lambda p: p.height)

