def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    items = ["1", "2", "3"]
    item_patches = {item: image_patch.find(item) for item in items}

    if not all(item_patches[item] for item in items):
        return image_patch

    # Sort each group by their vertical center
    for item in items:
        item_patches[item].sort(key=lambda p: p.vertical_center)

    # Find the middle item based on its vertical position
    middle_item = sorted(items, key=lambda item: item_patches[item][0].vertical_center)[1]
    middle_patches = item_patches[middle_item]

    # Check if the other two items are directly above or below the middle item
    top_item = sorted(items, key=lambda item: item_patches[item][0].vertical_center)[0]
    bottom_item = sorted(items, key=lambda item: item_patches[item][0].vertical_center)[-1]

    if len(middle_patches) == 1 and len(item_patches[top_item]) == 1 and len(item_patches[bottom_item]) == 1:
        top_patch = item_patches[top_item][0]
        bottom_patch = item_patches[bottom_item][0]

        if abs(top_patch.vertical_center - middle_patches[0].vertical_center) < abs(bottom_patch.vertical_center - middle_patches[0].vertical_center):
            return top_patch
        else:
            return bottom_patch

    return middle_patches[0]

